-- ALE-PRAC-005
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-005-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-005'), 3, 'Construction Management (CM) at Risk Delivery', 'Architectural Practice and Jurisprudence', 'service_delivery_method'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_application','case_scenario'], '[{"text": "CM at Risk Definition & Structure", "type": "heading"}, {"text": "CM at Risk — Construction Manager hired early in design phase; provides cost estimating and constructability advice during design; transitions to contractor role during construction with guaranteed maximum price (GMP)", "type": "definition"}, {"text": "Three-party arrangement: Owner, Architect (design authority), CM at Risk (construction execution with cost guarantee)", "type": "fact"}, {"text": "CM at Risk Phases", "type": "heading"}, {"text": "Pre-Construction — CM hired at start of design; provides cost consulting, schedule development, constructability review, value engineering proposals during SD and DD phases", "type": "fact"}, {"text": "Guaranteed Maximum Price (GMP) Establishment — At CD phase completion, CM commits to GMP cost ceiling; any overages CM''s responsibility", "type": "fact"}, {"text": "Construction — CM executes work; cost/schedule control; incentive arrangements may reward cost/schedule savings", "type": "fact"}, {"text": "Key Advantages", "type": "heading"}, {"text": "Early CM involvement — Constructability optimization during design phase (similar to Design-Build benefits)", "type": "fact"}, {"text": "Cost certainty — GMP provides owner cost ceiling; savings shared per incentive agreement", "type": "fact"}, {"text": "Design-construction collaboration — CM cost expertise integrated with architect''s design authority", "type": "fact"}, {"text": "Accelerated schedule — Phased construction possible while design ongoing (fast-track delivery)", "type": "fact"}, {"text": "Exam Tip: CM at Risk combines benefits of DBB clarity with accelerated scheduling; frequently compared to Design-Build in scenario questions", "type": "exam_tip"}]'::jsonb, true, false, false, false, 'ale-prac-005-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
