SELECT 'ALE-PRAC-005-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-005'), 3, 'Comprehensive Architectural Services (SPP 206)', 'Architectural Practice and Jurisprudence', 'service_delivery_method'::public.taxonomy_node_type, 'low'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 1, ARRAY['mcq_recall'], '[{"text": "Comprehensive Architectural Services Definition", "type": "heading"}, {"text": "SPP 206 addresses integrated service delivery from conception through occupancy, combining design, supervision, project management, and post-construction services in unified scope", "type": "fact"}, {"text": "Service Components", "type": "heading"}, {"text": "Complete design services (Pre-Design through Contract Documents phases)", "type": "fact"}, {"text": "Fulltime supervision during construction", "type": "fact"}, {"text": "Project management and cost control", "type": "fact"}, {"text": "Post-construction services and closeout", "type": "fact"}, {"text": "Compensation — Typically lump sum or percentage of PCC covering all phases, ranging 10%-18% of PCC depending on scope integration", "type": "formula"}]'::jsonb, true, false, false, false, 'ale-prac-005-04'
