-- ALE-PRAC-007
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-007-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-007'), 3, 'ADC Framework, Definitions & Organization', 'Architectural Practice and Jurisprudence', 'service_delivery_method'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Architectural Design Competition (ADC) Purpose & Framework", "type": "heading"}, {"text": "SPP 208 Purpose: ''To state the principles upon which competitions are based and by which promoters/owners should be guided in organizing ADCs. It has been drawn up in the interest of both project proponents/owners and competitors.''", "type": "code_provision"}, {"text": "ADC Core Participants — Defined Roles", "type": "heading"}, {"text": "Owner — Project proponent/promoter responsible for ADC organization and project implementation", "type": "definition"}, {"text": "Jury — Composed of majority architects with assistance of lay juror(s); nominated by Owner and approved by IAPOA (Integrated Association of Professional Organizations in Architecture)", "type": "definition"}, {"text": "Professional Advisor — Hired by Owner and approved by IAPOA to organize and manage ADC administration, contestant communications, documentation", "type": "definition"}, {"text": "Technical Advisors — Specialists (engineers, cost estimators, etc.) assisting jury in design evaluation for technical feasibility", "type": "definition"}, {"text": "Competition Secretariat — Administrative office managing entries, correspondence, payments, and operational logistics", "type": "definition"}, {"text": "IAPOA ADC Committee — Oversight body ensuring competition procedures comply with SPP 208 and professional standards", "type": "definition"}, {"text": "Conditions — ADC Documentation Package", "type": "heading"}, {"text": "Program document — Project brief, objectives, requirements, constraints", "type": "fact"}, {"text": "Instructions to competitors — Submission requirements, format specifications, evaluation criteria, prize structure", "type": "fact"}, {"text": "Site plans and maps — Topographic maps, utilities, adjacent developments, access routes", "type": "fact"}, {"text": "Entry forms and official envelopes — Standardized submission format, anonymity protection procedures", "type": "fact"}, {"text": "Sample conditions prepared by Professional Advisor ensuring clarity and fairness", "type": "detail"}]'::jsonb, true, false, false, false, 'ale-prac-007-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-007-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-007'), 3, 'ADC Types & Classification', 'Architectural Practice and Jurisprudence', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 1, ARRAY['mcq_recall','mcq_application'], '[{"text": "Two ADC Classifications per SPP 208", "type": "heading"}, {"text": "Project ADCs — Competitions for actual projects with intent for implementation; winning design selected for construction", "type": "definition"}, {"text": "Characteristics: Realistic budgets and technical requirements; design intended for built implementation; client has commitment to proceed with construction", "type": "fact"}, {"text": "Prize structure: First prize (typically winning design with construction contract); Second and Third prizes (honorarium payments)", "type": "fact"}, {"text": "Ideas Competitions — Design and planning exercises to elucidate a problem or explore design direction without implementation commitment", "type": "definition"}, {"text": "Characteristics: Conceptual/exploratory competitions; design may not be built; serves to gather design ideas and test approaches", "type": "fact"}, {"text": "Prize structure: Awards (first, second, third) with prize money but no construction contract", "type": "fact"}, {"text": "Common uses: Student competitions, design concept exploration, urban design vision competitions, specialized use studies", "type": "fact"}, {"text": "Exam Tip: ADC types clearly differentiate by implementation intent; test questions ask distinction between Project and Ideas competitions", "type": "exam_tip"}]'::jsonb, true, false, false, false, 'ale-prac-007-02'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
