SELECT 'ALE-PRAC-007-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-007'), 3, 'ADC Procedures & Professional Standards', 'Architectural Practice and Jurisprudence', 'professional_standard'::public.taxonomy_node_type, 'low'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "ADC Execution Principles", "type": "heading"}, {"text": "Transparency — Clear rules, evaluation criteria, prize structure published before competition", "type": "fact"}, {"text": "Fairness — Jury composed of qualified professionals; anonymous entry system protecting competitor identity until awards", "type": "fact"}, {"text": "Professional Standards — Competition procedures comply with SPP 208 and IAPOA oversight", "type": "fact"}, {"text": "Honoring Winning Design — Owner commits to implementing/honoring winning design (for Project ADCs) or acknowledging winning design (for Ideas competitions)", "type": "fact"}, {"text": "Competitor Benefits in ADC", "type": "heading"}, {"text": "Exposure and recognition for winning designs; prize monetary awards; potential for construction contract (Project ADCs); professional development opportunity", "type": "fact"}, {"text": "Owner Benefits in ADC", "type": "heading"}, {"text": "Access to multiple design solutions; innovative design exploration; competitive pricing pressure; professional design quality assurance through jury review", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-prac-007-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();

-- ALE-PRAC-008
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-008-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-008'), 3, 'PACS Definition, Scope & Government Policy', 'Architectural Practice and Jurisprudence', 'service_delivery_method'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Professional Architectural Consulting Services (PACS) Definition", "type": "heading"}, {"text": "SPP 209 addresses consulting services scope for government agencies and private sector regularly hiring consultants for maximum efficiency, economy, and expediency in: program/project concepts, pre-feasibility and feasibility studies, project evaluations, design preparation, management, and related activities", "type": "definition"}, {"text": "Government Priority Policy", "type": "heading"}, {"text": "Letter of Instruction No. 1000 directs Philippine government agencies to give priority to Filipino professionals in hiring consulting services", "type": "code_provision"}, {"text": "RA 9266 Architecture Act of 2004 defines Consulting Architects as professionals qualified to provide PACS", "type": "code_provision"}, {"text": "National Capability Building Strategy", "type": "heading"}, {"text": "SPP 209 emphasizes: ''One important strategy for strengthening national capability in the field of consulting services is the full utilization of local expertise.''", "type": "code_provision"}, {"text": "Consulting service provisions in SPP 209 are compatible with: national policies on local professional priority, accepted professional practices in consulting, government agency regulations", "type": "fact"}, {"text": "PACS Applicable Sectors", "type": "heading"}, {"text": "Government agencies — Department of Public Works (DPWH), Bureau of Internal Revenue (BIR), Department of Education (DepEd), local government units (LGUs)", "type": "fact"}, {"text": "Private sector — Real estate developers, corporations, financial institutions, manufacturing companies", "type": "fact"}, {"text": "Multilateral/Bilateral agencies — World Bank, Asian Development Bank (ADB), bilateral development agencies", "type": "fact"}, {"text": "Exam Tip: PACS emphasizes government priority for local professionals; focus on RA 9266 definition of Consulting Architect and Letter of Instruction No. 1000", "type": "exam_tip"}]'::jsonb, true, false, false, false, 'ale-prac-008-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-008-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-008'), 3, 'PACS Service Types & Engagement', 'Architectural Practice and Jurisprudence', 'service_delivery_method'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "PACS Service Categories", "type": "heading"}, {"text": "Program/Project Concepts — Defining client requirements, objectives, constraints, alternative approaches", "type": "fact"}, {"text": "Pre-Feasibility Studies — Preliminary assessment of project viability, technology options, risk factors, implementation roadmap", "type": "fact"}, {"text": "Feasibility Studies — Detailed technical and financial analysis, market assessment, implementation schedule, detailed budgets", "type": "fact"}, {"text": "Project Evaluations — Performance assessment of completed/ongoing projects, lessons learned, improvement recommendations", "type": "fact"}, {"text": "Design & Plan Preparation — Full design services including master plans, detailed design, construction documents", "type": "fact"}, {"text": "Management Services — Project management, coordination, supervision, quality assurance during implementation", "type": "fact"}, {"text": "Engagement Procedures", "type": "heading"}, {"text": "Consultant selection: Qualifications-based selection (QBS) preferred; competitive bidding on fixed scope; single-source selection for specialized expertise", "type": "fact"}, {"text": "Contract terms: Lump sum or time-and-materials; terms and conditions aligned with government regulations or client procurement policies", "type": "fact"}, {"text": "Compensation structures: Per SPP PACS provisions compatible with national policies and accepted professional practices", "type": "fact"}, {"text": "Exam Tip: PACS emphasizes consultant selection procedures and service definition; likely test questions involve matching service type to client need", "type": "exam_tip"}]'::jsonb, true, false, false, false, 'ale-prac-008-02'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();

-- ALE-PRAC-009
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-009-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-009'), 3, 'Philippine Construction Contract Framework (PD 1594, E.O. 1008)', 'Architectural Practice and Jurisprudence', 'code_provision'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Primary Philippine Construction Contract Laws", "type": "heading"}, {"text": "PD 1594 (Prescribing the Policies and Implementing Guidelines for Government Infrastructure and Development Projects) — Primary standard for government-funded projects; defines contractor responsibilities, bidding procedures, contract conditions, payment terms", "type": "code_provision"}, {"text": "E.O. 1008 (Establishment of the National Program for Infrastructure Development) — Executive Order relating to infrastructure procurement; coordinates with PD 1594", "type": "code_provision"}, {"text": "PD 1746 (Prescribing the Policies, Guidelines, Rules and Regulations for the Procurement, Management, Use and Maintenance of Roads and Highways) — Specific to transportation infrastructure", "type": "code_provision"}, {"text": "CIAP Doc 102 (Construction Industry Arbitration Commission Document 102) — Standard contract terms for private sector construction; alternative to government standard forms", "type": "code_provision"}, {"text": "Contract Administration Principles", "type": "heading"}, {"text": "Contract clarity — Complete scope definition, payment terms, schedule, quality standards; minimizes disputes", "type": "fact"}, {"text": "Change management — Formal procedures for scope changes, cost adjustments, schedule impacts documented and approved before work proceeds", "type": "fact"}, {"text": "Payment procedures — Milestone-based or progress payments; payment certification by architect/engineer; contractor invoice documentation", "type": "fact"}, {"text": "Dispute escalation — Contractor/owner disputes escalated through: site-level resolution → consultant review → formal mediation/arbitration", "type": "fact"}, {"text": "Exam Tip: Government projects heavily tested due to PD 1594 prevalence; focus on contract conditions, payment procedures, change order processes", "type": "exam_tip"}]'::jsonb, true, false, false, false, 'ale-prac-009-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-009-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-009'), 3, 'Contract Types & Conditions', 'Architectural Practice and Jurisprudence', 'professional_standard'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application','case_scenario'], '[{"text": "Fixed-Price (Lump Sum) Contract", "type": "heading"}, {"text": "Contractor agrees to fixed price for complete scope; contractor assumes cost overrun risk; price adjustment only for approved change orders", "type": "definition"}, {"text": "Appropriate for: Well-defined scopes with detailed designs; stable material costs; low risk of unforeseen conditions", "type": "fact"}, {"text": "Cost-Plus Contract", "type": "heading"}, {"text": "Contractor paid for actual costs (labor, materials, equipment) plus agreed markup (percentage or fixed amount)", "type": "definition"}, {"text": "Appropriate for: Uncertain scopes; renovation/adaptive reuse with unknown conditions; research/specialized projects; emergency repairs", "type": "fact"}, {"text": "Unit Price Contract", "type": "heading"}, {"text": "Contractor paid per unit of work (e.g., PHP per cubic meter excavation, per linear meter road); total cost varies with actual quantities", "type": "definition"}, {"text": "Appropriate for: Projects with quantity uncertainty (earthwork, rock excavation); government projects (PD 1594 preferred method)", "type": "fact"}, {"text": "Design-Build Fixed-Price Contract", "type": "heading"}, {"text": "Contractor/design-builder assumes both design and construction responsibility for fixed price; combines scope and execution risk", "type": "definition"}, {"text": "Appropriate for: Integrated design-build delivery; cost-conscious clients; experienced design-builders with similar project history", "type": "fact"}, {"text": "Contract Conditions (General)", "type": "heading"}, {"text": "Scope of work — Detailed description of deliverables, specifications, performance standards", "type": "fact"}, {"text": "Contract price and payment terms — Total contract amount, payment schedule (lump sum phases, milestone payments, monthly progress), retainage percentage", "type": "fact"}, {"text": "Performance schedule — Project start date, milestone dates, substantial completion date; liquidated damages for delay", "type": "fact"}, {"text": "Quality standards — Referenced codes (NSCP, NSCB), specification compliance, testing/inspection procedures, defects liability period", "type": "fact"}, {"text": "Change order procedures — Process for scope changes, cost adjustments, schedule impacts; approval authority and documentation requirements", "type": "fact"}, {"text": "Warranty & Defects Liability — Contractor responsibility period post-completion (typically 1 year); repair/correction of defective work", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-prac-009-02'
FROM public.disciplines d WHERE d.acronym = 'ALE'
