INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-PRAC-009-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-PRAC-009'), 3, 'Change Management & Dispute Resolution', 'Architectural Practice and Jurisprudence', 'professional_standard'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_application','case_scenario'], '[{"text": "Change Order Process", "type": "heading"}, {"text": "Identification — Contractor or owner identifies scope change/variation from contract documents", "type": "fact"}, {"text": "Documentation — Change request prepared with: description of change, reason/justification, cost impact, schedule impact, drawings/details if applicable", "type": "fact"}, {"text": "Evaluation — Architect/consultant reviews for: scope clarification, design impact, cost reasonableness, schedule feasibility", "type": "fact"}, {"text": "Approval — Owner approval required before contractor proceeds with changed work; change order signed by all parties documenting new contract price/schedule", "type": "fact"}, {"text": "Types of Changes", "type": "heading"}, {"text": "Design changes — Modifications to architectural design; may be owner-initiated or contractor-proposed value engineering", "type": "fact"}, {"text": "Unforeseen conditions — Existing conditions discovered during construction not evident from original documents (e.g., subsurface obstacles, hidden structural conditions)", "type": "fact"}, {"text": "Differing site conditions — Soil composition, groundwater, utilities different from contract assumptions; contractor entitled to cost/schedule adjustment per contract terms", "type": "fact"}, {"text": "Dispute Resolution Procedures", "type": "heading"}, {"text": "Site-level negotiation — Contractor, owner representative, architect attempt resolution at project site; most disputes resolved at this level", "type": "fact"}, {"text": "Formal mediation — Neutral third party (architect or mediator) facilitates discussion; less formal than arbitration; confidential", "type": "fact"}, {"text": "Arbitration — Construction Industry Arbitration Commission (CIAC) proceedings per Rule 50-D Civil Code (as amended); binding decision; faster than litigation", "type": "fact"}, {"text": "Litigation — Court proceedings (last resort); slower and more expensive; used when other methods fail", "type": "fact"}, {"text": "Architect''s Role in Disputes", "type": "heading"}, {"text": "Neutral reviewer — Architect makes decisions on contract interpretation, design compliance, change order merit; decisions binding unless appealed", "type": "fact"}, {"text": "Mediator — Facilitates resolution discussions between contractor and owner; recommends fair approaches", "type": "fact"}, {"text": "Document preservation — Maintains all correspondence, site records, inspection photos, change documentation supporting decisions", "type": "fact"}, {"text": "Exam Tip: Change order processes and dispute resolution are high-frequency test items; understand four-step change process and escalation procedures", "type": "exam_tip"}]'::jsonb, true, false, false, false, 'ale-prac-009-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
