-- ── Step 3: Update wiki_items on existing nodes ─────────────────────
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Code of Ethics Overview", "type": "heading"}, {"text": "RA 9266 (Architecture Act of 2004) establishes professional conduct standards for registered architects", "type": "code_provision"}, {"text": "Ethical principles include: (1) Integrity in professional relationships; (2) Competence through continuous learning; (3) Responsibility to public welfare and environment; (4) Honesty in financial dealings", "type": "fact"}, {"text": "Architects must maintain professional independence and avoid conflicts of interest", "type": "detail"}, {"text": "Professional responsibility extends to public safety, structural integrity, and environmental sustainability", "type": "detail"}, {"text": "Exam Tip: RA 9266 Article on Code of Ethics frequently tested; focus on conflict of interest scenarios and public welfare prioritization", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-001-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "CPD Requirement per RA 9266", "type": "heading"}, {"text": "45 CPD units required per 3-year compliance period (15 units/year average)", "type": "code_provision"}, {"text": "CPD compliance mandatory for license renewal and continued professional practice", "type": "fact"}, {"text": "Acceptable CPD activities: seminars, conferences, workshops, formal education, self-directed learning, publications", "type": "detail"}, {"text": "PRC Board of Architecture monitors and verifies CPD compliance through audit", "type": "detail"}, {"text": "Exam Tip: Critical detail — 45 units per 3-year period; commonly tested in LAWS section but applies to all practice subtopics", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-001-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Article 1723 Civil Code — Architect''s Liability", "type": "heading"}, {"text": "Architects are jointly and severally liable with contractors for structural and material defects discovered within 10 years from project completion", "type": "code_provision"}, {"text": "10-year prescriptive period — counted from date of project completion (turnover/final acceptance by client), not from date of discovery", "type": "detail"}, {"text": "Liability applies to defects in: (1) Structural design and integrity; (2) Material specifications and quality; (3) Construction methods and execution oversight", "type": "fact"}, {"text": "Joint and several liability means client can sue architect and/or contractor for full damages; either party may recover from the other", "type": "detail"}, {"text": "Architect can limit liability through: (1) Clear scope of services definition; (2) Proper design review and documentation; (3) Contractor supervision and inspection records; (4) Professional insurance coverage", "type": "detail"}, {"text": "Exam Tip: Article 1723 is high-frequency testing item; critical distinction — 10 years from completion, not from defect discovery. Common exam trap question", "type": "exam_tip"}, {"text": "Warning: Architects cannot disclaim liability for structural defects or material failures covered under Article 1723", "type": "warning"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-001-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Five Standard Design Phases per SPP 202", "type": "heading"}, {"text": "Phase 1: Pre-Design — Project definition, site analysis, program development, feasibility assessment, budget estimation (5-10% of design effort)", "type": "fact"}, {"text": "Phase 2: Schematic Design (SD) — Conceptual design development, space planning, basic systems design, cost estimation, client approval (15-20% of design effort)", "type": "fact"}, {"text": "Phase 3: Design Development (DD) — Detailed design refinement, systems coordination, material selection, preliminary specifications, cost refinement (20-25% of design effort)", "type": "fact"}, {"text": "Phase 4: Contract Documents (CD) — Preparation of construction documents including plans, specifications, details, and bid/contract documents (30-40% of design effort)", "type": "fact"}, {"text": "Phase 5: Bidding & Negotiation — Bidding assistance, contractor selection, contract negotiation, scope clarifications (5-10% of design effort)", "type": "fact"}, {"text": "Architect''s deliverables include: drawings, specifications, cost estimates, project schedules, and construction supervision scope definition", "type": "detail"}, {"text": "Exam Tip: Design phase breakdown and percentage effort allocation frequently tested in scenario questions; phases must be clearly differentiated", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-002-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Percentage of Project Construction Cost (PCC) Method", "type": "heading"}, {"text": "Typical range: 5% to 12% of total Project Construction Cost (materials, labor, equipment, contractor overhead, profit)", "type": "formula"}, {"text": "Factors affecting percentage: project size (smaller = higher %), project complexity, location, service scope, client type", "type": "detail"}, {"text": "Example: PHP 10,000,000 construction cost × 8% = PHP 800,000 architectural fee", "type": "formula"}, {"text": "Percentage allocation across phases: Pre-Design 5%, SD 20%, DD 20%, CD 40%, Bidding 15%", "type": "detail"}, {"text": "Variations based on: project type (residential, commercial, institutional), new vs. renovation, and design complexity", "type": "detail"}, {"text": "Exam Tip: PCC method is most common in Philippine practice; test questions often ask for fee calculations given construction cost and percentage rate", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-002-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Pre-Design Deliverables", "type": "heading"}, {"text": "Site analysis (location, topography, utilities, zoning, environmental factors), program documentation, preliminary budgets, project schedules, design objectives", "type": "fact"}, {"text": "Schematic Design Deliverables", "type": "heading"}, {"text": "Schematic plans (site plan, floor plans, elevations, sections at 1:100 or 1:200 scale), conceptual systems drawings, preliminary cost estimate, design narrative, massing models", "type": "fact"}, {"text": "Design Development Deliverables", "type": "heading"}, {"text": "Detailed floor plans, wall sections, material specifications, MEP systems coordination, detailed cost estimate with breakdown, project timeline", "type": "fact"}, {"text": "Contract Documents Deliverables", "type": "heading"}, {"text": "Final construction drawings (plans, elevations, sections, details at appropriate scales), complete specifications (CSI format), bill of materials, bidding documents, contract conditions", "type": "fact"}, {"text": "Quality standards: All documents must be clear, complete, coordinated, and sufficient for contractor bidding and construction execution", "type": "detail"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-002-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "23 Types of Specialized Architectural Services per SPP 203", "type": "heading"}, {"text": "Interior Design Services — space planning, finishes, furnishings, lighting design, and color coordination for interior spaces", "type": "fact"}, {"text": "Landscape Design Services — site planning, planting design, hardscape design, water features, outdoor space coordination", "type": "fact"}, {"text": "Urban Design & Master Planning — district-scale planning, streetscape design, public space design, development corridors", "type": "fact"}, {"text": "Historic Preservation & Restoration — heritage assessment, restoration design, adaptive reuse, conservation planning", "type": "fact"}, {"text": "Feasibility Studies — technical and financial viability assessment, market analysis, development potential analysis", "type": "fact"}, {"text": "Environmental Design & Sustainability Consulting — green building design, BERDE/LEED certification support, energy analysis", "type": "fact"}, {"text": "Building Information Modeling (BIM) Coordination — 3D modeling, clash detection, coordinated documentation, quantity takeoffs", "type": "fact"}, {"text": "Cost Estimation & Value Engineering — detailed cost analysis, life-cycle costing, cost optimization strategies", "type": "fact"}, {"text": "Exam Tip: SPP 203 lists all 23 specialized services; likely test question format is scenario matching service type to client need", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-003-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Specialized Service Compensation Methods", "type": "heading"}, {"text": "Specialized services typically compensated by: (1) Lump Sum fixed fee; (2) Hourly/daily rates; (3) Percentage of relevant cost component; (4) Professional fee plus expenses", "type": "fact"}, {"text": "Interior Design: typically 8-15% of furniture/finishes cost, or lump sum based on scope (space area and complexity)", "type": "formula"}, {"text": "Landscape Design: typically 5-10% of landscape construction cost, or per-area rates (PHP/sqm)", "type": "formula"}, {"text": "Master Planning: typically fixed fee or per-area rate ranging PHP 500-2,000 per hectare depending on complexity and analysis depth", "type": "formula"}, {"text": "Feasibility Studies: typically fixed fee (PHP 100,000-500,000+) based on study scope and complexity", "type": "formula"}, {"text": "Exam Tip: Specialized services compensation is highly variable; test questions focus on appropriate method selection and factor analysis rather than specific percentages", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-003-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Fulltime Supervision Definition & Scope", "type": "heading"}, {"text": "Fulltime supervision — Architect''s resident representative present at construction site during construction period, directly responsible to architect for: quality control, work compliance with documents, schedule monitoring, change management", "type": "definition"}, {"text": "Supervisor responsibilities: (1) Daily site inspections and progress documentation; (2) Quality control and material testing; (3) Safety compliance oversight; (4) RFI (Request for Information) processing; (5) Change order documentation and approval", "type": "fact"}, {"text": "Compensation Range: 1% to 1.5% of Project Construction Cost (PCC)", "type": "code_provision"}, {"text": "Example: PHP 10,000,000 construction cost × 1.25% = PHP 125,000 supervision fee", "type": "formula"}, {"text": "Factors affecting supervision fee: project size, duration, complexity, location, materials sophistication, construction methods", "type": "detail"}, {"text": "Exam Tip: 1%-1.5% of PCC is the key range to memorize; frequently tested in fee calculation scenarios", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-004-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Construction Management (CM) Definition & Rationale", "type": "heading"}, {"text": "CM Services address increasing project complexity and demand for effective cost control and faster implementation. Architect can serve as CM to coordinate various specialties and ensure quality/cost/schedule management.", "type": "fact"}, {"text": "CM Structure — Three Possible Arrangements", "type": "heading"}, {"text": "CM as staff member — Employed directly by owner as internal project manager", "type": "fact"}, {"text": "CM as independent individual — Architect or engineer hired as independent consultant CM", "type": "fact"}, {"text": "CM as firm — Specialized CM firm hired by owner to manage entire project execution", "type": "fact"}, {"text": "CM Responsibilities — Construction Supervision Group (CSG) Functions", "type": "heading"}, {"text": "Coordination & Supervision — Schedule management, contractor coordination, subcontractor management, progress reporting", "type": "fact"}, {"text": "Cost Control — Budget monitoring, change order management, cost tracking, payment processing, financial reporting", "type": "fact"}, {"text": "Quality Control — Inspection, testing, compliance verification, material approval, workmanship standards enforcement", "type": "fact"}, {"text": "Records Management — Project documentation, meeting minutes, inspection records, correspondence, as-built drawings", "type": "fact"}, {"text": "CM Legal Responsibility & Liability Limitations", "type": "heading"}, {"text": "Architect as CM is directly responsible to Owner for all aspects: programming, coordination, quality control, cost control, time management", "type": "code_provision"}, {"text": "CM assumes NO liability if: (1) Equipment fails or building collapses due to design deficiencies (if CM did not participate in design review/approval); (2) Construction defects result from contractor''s methods/execution (if CM faithfully discharged oversight duties)", "type": "detail"}, {"text": "CM Scope Limitations — Article 1723 Civil Code Protection", "type": "heading"}, {"text": "CM shall NOT involve directly with contractor work in manner that implies CM is assuming contractor''s liability (per Civil Code Article 1723)", "type": "code_provision"}, {"text": "CM shall NOT impose construction methods/systems/designs that substantially alter schedule or impair architect''s original design concept", "type": "code_provision"}, {"text": "Exam Tip: CM liability framework is complex and frequently tested; focus on three-role structure, CSG functions, and liability scope limitations", "type": "exam_tip"}, {"text": "Warning: CM role is supervisory/administrative, not contractor responsibility; CM cannot assume builder''s duties without triggering Article 1723 liability shift", "type": "warning"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-004-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Post-Construction Service Categories", "type": "heading"}, {"text": "Building Administration — Project closeout, warranty review, punch list completion, final inspections, occupancy certification", "type": "fact"}, {"text": "Facilities Management — Operations planning, preventive maintenance programs, capital improvement planning, energy management", "type": "fact"}, {"text": "Building Commissioning — System startup, performance verification, operator training, performance optimization", "type": "fact"}, {"text": "Maintenance Program Development — Annual maintenance schedules, lifecycle costing, replacement planning, record keeping", "type": "fact"}, {"text": "Post-Construction Compensation", "type": "heading"}, {"text": "Typically charged as: (1) Percentage of PCC (0.5%-2%); (2) Per-diem hourly rates; (3) Fixed monthly fees for FM services; (4) Time-and-materials", "type": "formula"}, {"text": "Exam Tip: Post-construction services often overlooked in exam; questions test understanding that architect''s responsibility extends beyond construction completion", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-004-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Design-Bid-Build (DBB) Method — Sequential Process", "type": "heading"}, {"text": "Design Phase — Architect completes 100% design (plans, specifications, contract documents) before construction begins", "type": "fact"}, {"text": "Bidding Phase — Contractor selection through competitive bidding based on complete design documents; pricing based on fully defined scope", "type": "fact"}, {"text": "Construction Phase — Contractor executes work according to architect''s design; architect provides administration and supervision", "type": "fact"}, {"text": "Key Characteristics & Advantages", "type": "heading"}, {"text": "Clear division of responsibility — Architect designs, Contractor builds (distinct contracts and responsibilities)", "type": "fact"}, {"text": "Fixed-price bidding — Contractor liability fixed at bid amount; cost certainty for owner", "type": "fact"}, {"text": "Competitive bidding pressure — Multiple contractors compete on same scope, driving cost efficiency", "type": "fact"}, {"text": "Design completion before construction — Allows thorough design review, phasing, and cost estimation before commitment", "type": "fact"}, {"text": "Key Disadvantages", "type": "heading"}, {"text": "Extended project timeline — Sequential phases (design → bidding → construction) delay project completion", "type": "fact"}, {"text": "Limited design optimization for constructability — Design completed before contractor input on methods/sequencing", "type": "fact"}, {"text": "Change order risks — Design omissions discovered during construction lead to change orders and delays", "type": "fact"}, {"text": "Exam Tip: DBB is most traditional method; frequently used in government and institutional projects; test questions often compare DBB to Design-Build", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-005-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Design-Build (DB) Rationale — Balancing Time, Quality, Cost", "type": "heading"}, {"text": "SPP 207 states: ''In any building project, there is need to balance the elements of time, quality and cost, which, in many cases, can best be achieved by the Architect performing Design-Build Services.''", "type": "code_provision"}, {"text": "Design-Build Services by Administration — Five Phases", "type": "heading"}, {"text": "Phase 1: Project Definition — Program development, budget establishment, site analysis, preliminary design direction", "type": "fact"}, {"text": "Phase 2: Schematic Design — Concept development, cost estimation, design narrative, client approval of direction", "type": "fact"}, {"text": "Phase 3: Design Development — Detailed design, systems coordination, specifications, refined cost estimate", "type": "fact"}, {"text": "Phase 4: Contract Documents — Final construction documents and bid/contract documents", "type": "fact"}, {"text": "Phase 5: Construction — Job site management with integrated design oversight and quality control", "type": "fact"}, {"text": "Architect''s Integrated Responsibilities — Design-Build by Administration", "type": "heading"}, {"text": "Schedule preparation and project timeline management", "type": "fact"}, {"text": "Contractor hiring and subcontractor management", "type": "fact"}, {"text": "Material procurement oversight and approval", "type": "fact"}, {"text": "Account authorization and financial management", "type": "fact"}, {"text": "Government negotiation and regulatory compliance", "type": "fact"}, {"text": "Business transaction management and contract administration", "type": "fact"}, {"text": "Design-Build with Guaranteed Maximum Project Construction Cost", "type": "heading"}, {"text": "Architect provides guaranteed maximum cost (GMPC) ceiling to client; if construction costs exceed GMPC, architect absorbs overages", "type": "fact"}, {"text": "GMPC approach incentivizes cost control and efficiency through architect''s financial risk sharing", "type": "detail"}, {"text": "Client receives cost certainty and architect motivation for value engineering", "type": "detail"}, {"text": "Key Advantages of Design-Build", "type": "heading"}, {"text": "Accelerated schedule — Overlapping design and construction phases reduce total project duration", "type": "fact"}, {"text": "Single point of responsibility — Architect manages integrated design-construction execution", "type": "fact"}, {"text": "Constructability integration — Contractor input during design phase improves build-ability and cost optimization", "type": "fact"}, {"text": "Value engineering — Integrated team identifies cost-saving alternatives during design phase", "type": "fact"}, {"text": "Exam Tip: Design-Build has become increasingly common in Philippines; test questions focus on five-phase structure and comparison with DBB", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-005-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "PCC Method Definition & Application", "type": "heading"}, {"text": "Professional fee = Percentage rate × Total Project Construction Cost (PCC)", "type": "formula"}, {"text": "Project Construction Cost includes: direct materials, labor, equipment, contractor overhead, contractor profit (excludes architect/consultant fees and owner costs)", "type": "definition"}, {"text": "Typical Fee Ranges by Service Type", "type": "heading"}, {"text": "Design Services (Design-Bid-Build): 5-12% of PCC", "type": "formula"}, {"text": "Design-Build Services: 6-14% of PCC (higher due to integrated responsibility)", "type": "formula"}, {"text": "Supervision Only (fulltime): 1-1.5% of PCC", "type": "formula"}, {"text": "Design + Supervision: 7-14% of PCC combined", "type": "formula"}, {"text": "Interior Design: 8-15% of furniture/finishes component", "type": "formula"}, {"text": "Fee Adjustment Factors", "type": "heading"}, {"text": "Project size — Inverse relationship: larger projects typically lower percentage (5-6%), smaller projects higher percentage (10-12%)", "type": "fact"}, {"text": "Project complexity — Complex projects (hospitals, R&D facilities): 10-12%; Standard projects (offices, residential): 6-8%; Simple projects (warehouses): 5-6%", "type": "fact"}, {"text": "Project type — Residential lower (5-8%), Commercial standard (7-10%), Institutional/Specialized higher (10-12%)", "type": "fact"}, {"text": "Geographic location — Metro Manila lower (5-8%), Provincial higher (8-10%)", "type": "fact"}, {"text": "Service scope — Full services higher; limited services lower percentage", "type": "fact"}, {"text": "Calculation Example", "type": "heading"}, {"text": "Commercial office building: PHP 50,000,000 construction cost × 8% = PHP 4,000,000 architectural fee", "type": "formula"}, {"text": "Residential complex: PHP 20,000,000 construction cost × 7% = PHP 1,400,000 architectural fee", "type": "formula"}, {"text": "Specialized facility: PHP 100,000,000 construction cost × 12% = PHP 12,000,000 architectural fee", "type": "formula"}, {"text": "Exam Tip: PCC method is most common and heavily tested; ability to calculate fees and understand adjustment factors is critical", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-006-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "MDPE Method Definition", "type": "heading"}, {"text": "Professional fee = MDPE factor × Total Direct Personnel Expense (salaries of architects and staff directly billable to project)", "type": "formula"}, {"text": "Direct Personnel Expense — Sum of all salaries/wages paid to architectural staff working on project (excludes overhead, office support, administration)", "type": "definition"}, {"text": "Typical MDPE Multipliers", "type": "heading"}, {"text": "MDPE 1.5 to 2.0x — Small specialized services or limited-scope projects", "type": "formula"}, {"text": "MDPE 2.0 to 2.5x — Standard design services with typical project scope", "type": "formula"}, {"text": "MDPE 2.5 to 3.5x — Complex projects with significant coordination requirements", "type": "formula"}, {"text": "MDPE 3.5 to 4.0x — Highly complex projects or design-build with integrated management", "type": "formula"}, {"text": "MDPE Calculation Example", "type": "heading"}, {"text": "Senior Architect salary: PHP 60,000/month × 12 months = PHP 720,000", "type": "formula"}, {"text": "Junior Architect salary: PHP 35,000/month × 12 months = PHP 420,000", "type": "formula"}, {"text": "Total Direct Personnel Expense = PHP 1,140,000", "type": "formula"}, {"text": "Professional Fee = PHP 1,140,000 × 2.5 MDPE = PHP 2,850,000", "type": "formula"}, {"text": "Advantages & Disadvantages", "type": "heading"}, {"text": "Advantages: Reflects actual staffing resources invested; fair allocation for complex projects; transparent cost accounting", "type": "fact"}, {"text": "Disadvantages: Requires detailed cost tracking; less predictable for client budgeting; complex for multi-phase projects", "type": "fact"}, {"text": "When to Use MDPE", "type": "heading"}, {"text": "Specialized consulting services with variable staffing levels", "type": "fact"}, {"text": "Long-duration projects requiring phased resource allocation", "type": "fact"}, {"text": "Complex coordination projects (master planning, large mixed-use developments)", "type": "fact"}, {"text": "Exam Tip: MDPE requires understanding of multiplier logic and staffing cost accounting; less frequently tested than PCC but important for professional services questions", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-006-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Lump Sum Fixed Fee Method", "type": "heading"}, {"text": "Architect quotes total fixed fee for defined scope of work; regardless of actual hours or expenses, fee remains fixed", "type": "definition"}, {"text": "Appropriate for: Well-defined, limited-scope projects; specialized services with clear deliverables; feasibility studies; master plans", "type": "fact"}, {"text": "Example: Historic preservation assessment = PHP 250,000 fixed fee for site analysis, condition survey, recommendations report", "type": "formula"}, {"text": "Advantages: Clear budgeting for owner; no scope creep unless documented; architect efficiency incentivized", "type": "fact"}, {"text": "Disadvantages: Architect risk if scope expands; difficult to estimate for uncertain projects; disputes over scope definition", "type": "fact"}, {"text": "Per Diem / Hourly Rate Method", "type": "heading"}, {"text": "Architect charges hourly or daily rate for time spent on project work; actual fee depends on hours/days worked", "type": "definition"}, {"text": "Typical rates: Senior Architect PHP 3,000-5,000/hour; Junior Architect PHP 1,500-2,500/hour; Architect-in-training PHP 800-1,200/hour", "type": "formula"}, {"text": "Appropriate for: Consulting services; project management oversight; extended post-construction services; expert witness work", "type": "fact"}, {"text": "Advantages: Fair allocation based on actual effort; flexible for uncertain duration projects; transparent billing", "type": "fact"}, {"text": "Disadvantages: Uncertain total cost for owner; less incentive for architect efficiency; disputed hour tracking", "type": "fact"}, {"text": "Professional Fee + Reimbursable Expenses Method", "type": "heading"}, {"text": "Architect charges: (1) Base professional fee (hourly rate, percentage, or fixed amount) + (2) Reimbursable expenses (travel, printing, model materials, consultant fees, reproduction costs)", "type": "definition"}, {"text": "Reimbursable expenses typically marked up 10-15% to cover handling/management overhead", "type": "fact"}, {"text": "Example: Design fee PHP 500,000 + expenses (travel PHP 50,000 + consultants PHP 100,000 + materials PHP 30,000) × 1.15 markup = PHP 725,000 total", "type": "formula"}, {"text": "Appropriate for: Services with significant external consultant involvement; extensive travel requirements; specialized studies", "type": "fact"}, {"text": "Exam Tip: All four methods tested; questions often ask selection of appropriate method given project characteristics; be able to calculate fees for each type", "type": "exam_tip"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-PRAC-006-03';

