  v_new INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_new FROM public.taxonomy_tree
  WHERE ale_id IN ('ALE-PRAC-001-04','ALE-PRAC-005-03','ALE-PRAC-005-04','ALE-PRAC-007-01','ALE-PRAC-007-02','ALE-PRAC-007-03','ALE-PRAC-008-01','ALE-PRAC-008-02','ALE-PRAC-009-01','ALE-PRAC-009-02','ALE-PRAC-009-03');
  RAISE NOTICE 'ALE-PRAC expansion: % / 11 new subtopics present.', v_new;
